/// String Base64 limpio y formateado para Silueta.jpg
const String kSiluetaBase64Clean =
    '';

/// Función auxiliar para formatear y padear strings base64 evitando FormatException
String padBase64String(String input) {
  final clean = input.replaceAll(RegExp(r'\s+'), '');
  final remainder = clean.length % 4;
  if (remainder == 0) return clean;
  return clean + ('=' * (4 - remainder));
}
